ALTER TABLE public.orders ADD COLUMN challenge_id uuid REFERENCES public.challenges(id) ON DELETE RESTRICT, ADD COLUMN reservation_expires_at timestamptz, ADD COLUMN challenge_cart jsonb;
ALTER TABLE public.orders DROP CONSTRAINT orders_offering_type_check, DROP CONSTRAINT orders_offering_target_check;
ALTER TABLE public.orders ADD CONSTRAINT orders_offering_type_check CHECK(offering_type IN('event','course','resource','membership','course_subscription','platform_plan','legacy','challenge'));
ALTER TABLE public.orders ADD CONSTRAINT orders_offering_target_check CHECK((offering_type='challenge' AND challenge_id IS NOT NULL AND num_nonnulls(event_id,offer_id,track_id,legacy_payment_id)=0) OR (challenge_id IS NULL AND ((offering_type='event' AND event_id IS NOT NULL AND num_nonnulls(offer_id,track_id,legacy_payment_id)=0) OR (offering_type='course' AND track_id IS NOT NULL AND num_nonnulls(event_id,offer_id,legacy_payment_id)=0) OR (offering_type IN('resource','membership','course_subscription') AND offer_id IS NOT NULL AND num_nonnulls(event_id,track_id,legacy_payment_id)=0) OR (offering_type='legacy' AND legacy_payment_id IS NOT NULL AND num_nonnulls(event_id,offer_id,track_id)=0) OR (offering_type='platform_plan' AND num_nonnulls(event_id,offer_id,track_id,legacy_payment_id)=0))));
ALTER TABLE public.order_items ADD COLUMN addon_key text, ADD COLUMN refunded_cents integer NOT NULL DEFAULT 0 CHECK(refunded_cents>=0);
ALTER TABLE public.order_items DROP CONSTRAINT order_items_item_type_check;
ALTER TABLE public.order_items ADD CONSTRAINT order_items_item_type_check CHECK(item_type IN('ticket','addon','course','resource','membership','plan','challenge'));
ALTER TABLE public.challenge_members ADD COLUMN order_id uuid REFERENCES public.orders(id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX challenge_buyer_pending_order ON public.orders(challenge_id,buyer_user_id) WHERE offering_type='challenge' AND status='pending';
CREATE OR REPLACE FUNCTION public.get_public_challenge(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('id',c.id,'title_en',c.title_en,'title_es',c.title_es,'description_en',c.description_en,'description_es',c.description_es,'starts_on',c.starts_on,'ends_on',c.ends_on,'is_paid',c.is_paid,'price_cents',coalesce(c.price_cents,0),'currency',c.currency,'enrollment',c.enrollment,'addons',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a->>'id','name',a->>'name','description',a->>'description','price_cents',(a->>'price_cents')::int,'max_quantity',coalesce((a->>'max_quantity')::int,1),'inventory',a->'inventory','available',coalesce((a->>'available')::boolean,true))) FROM jsonb_array_elements(c.addons) a),'[]'::jsonb)) FROM challenges c JOIN profiles p ON p.id=c.created_by WHERE c.id=_id AND c.status='published' AND c.enrollment='open' AND p.host_public AND NOT EXISTS(SELECT 1 FROM user_suspensions WHERE user_id=p.id) AND NOT EXISTS(SELECT 1 FROM team_suspensions WHERE team_id=c.team_id); $$;
REVOKE ALL ON FUNCTION public.get_public_challenge(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_public_challenge(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.create_challenge_order(_c uuid,_request uuid,_extras jsonb,_environment text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE c challenges; existing orders; oid uuid; s jsonb; a jsonb; cart jsonb:='[]'; seen text[]:='{}'; qty int; used int; total int; rule text; acct text;
BEGIN
 IF auth.uid() IS NULL OR _request IS NULL OR _environment NOT IN('sandbox','live') THEN RAISE EXCEPTION 'not_allowed'; END IF;
 SELECT * INTO c FROM challenges WHERE id=_c FOR UPDATE; IF NOT FOUND OR NOT challenge_can_enroll(_c) THEN RAISE EXCEPTION 'not_allowed'; END IF;
 IF challenge_member_active(_c,auth.uid()) THEN RETURN jsonb_build_object('enrolled',true); END IF;
 IF EXISTS(SELECT 1 FROM challenge_members WHERE challenge_id=_c AND user_id=auth.uid()) THEN RAISE EXCEPTION 'access_revoked'; END IF;
 IF jsonb_typeof(_extras) IS DISTINCT FROM 'array' OR jsonb_array_length(_extras)>8 THEN RAISE EXCEPTION 'invalid_addons'; END IF;
 SELECT * INTO existing FROM orders WHERE idempotency_key='challenge:'||auth.uid()::text||':'||_request::text;
 IF FOUND THEN IF existing.challenge_id<>_c OR existing.challenge_cart IS DISTINCT FROM _extras OR existing.environment<>_environment THEN RAISE EXCEPTION 'request_changed'; END IF; RETURN jsonb_build_object('id',existing.id,'status',existing.status,'total',existing.gross_cents); END IF;
 UPDATE orders SET status='cancelled',updated_at=now() WHERE challenge_id=_c AND status='pending' AND reservation_expires_at<=now();
 IF EXISTS(SELECT 1 FROM orders WHERE challenge_id=_c AND buyer_user_id=auth.uid() AND status='pending') THEN RAISE EXCEPTION 'checkout_pending'; END IF;
 IF c.capacity IS NOT NULL AND (SELECT count(*) FROM challenge_members WHERE challenge_id=_c AND access_status='active')+(SELECT count(*) FROM orders WHERE challenge_id=_c AND status='pending')>=c.capacity THEN RAISE EXCEPTION 'challenge_full'; END IF;
 total:=CASE WHEN c.is_paid THEN coalesce(c.price_cents,0) ELSE 0 END;
 FOR s IN SELECT value FROM jsonb_array_elements(_extras) LOOP
 SELECT value INTO a FROM jsonb_array_elements(c.addons) WHERE value->>'id'=s->>'id'; qty:=(s->>'quantity')::int;
 IF a IS NULL OR s->>'id'=ANY(seen) OR NOT coalesce((a->>'available')::boolean,true) OR qty IS NULL OR qty NOT BETWEEN 1 AND coalesce((a->>'max_quantity')::int,1) THEN RAISE EXCEPTION 'invalid_addons'; END IF;
 seen:=array_append(seen,s->>'id');
 SELECT coalesce(sum(quantity),0) INTO used FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.challenge_id=_c AND i.addon_key=s->>'id' AND o.status IN('pending','paid','partially_refunded');
 used:=used+coalesce((SELECT sum((x->>'quantity')::int) FROM challenge_members m CROSS JOIN LATERAL jsonb_array_elements(m.extras) x WHERE m.challenge_id=_c AND m.access_status='active' AND m.order_id IS NULL AND x->>'id'=s->>'id'),0);
 IF a->>'inventory' IS NOT NULL AND used+qty>(a->>'inventory')::int THEN RAISE EXCEPTION 'addon_sold_out'; END IF;
 total:=total+qty*(a->>'price_cents')::int; cart:=cart||jsonb_build_array(jsonb_build_object('id',a->>'id','name',a->>'name','description',a->>'description','quantity',qty,'unit_cents',(a->>'price_cents')::int));
 END LOOP;
 IF total=0 THEN RETURN enroll_challenge(_c,_extras); END IF;
 SELECT connect_account_id INTO acct FROM billing_accounts WHERE user_id=c.created_by AND connect_status='active';
 IF acct IS NULL THEN RAISE EXCEPTION 'checkout_setup_required'; END IF;
 rule:=active_fee_rule_for_plan('challenge',effective_plan(c.created_by)->>'plan'); IF rule IS NULL THEN RAISE EXCEPTION 'checkout_setup_required'; END IF;
 INSERT INTO orders(idempotency_key,offering_type,challenge_id,host_id,buyer_user_id,gross_cents,platform_fee_cents,fee_rule_id,currency,environment,connected_account_id,reservation_expires_at,challenge_cart) VALUES('challenge:'||auth.uid()::text||':'||_request::text,'challenge',_c,c.created_by,auth.uid(),total,calc_platform_fee_cents(total,rule),rule,c.currency,_environment,acct,now()+interval '30 minutes',_extras) RETURNING id INTO oid;
 INSERT INTO order_items(order_id,item_type,description,quantity,unit_cents) VALUES(oid,'challenge',coalesce(nullif(c.title_en,''),c.title_es),1,CASE WHEN c.is_paid THEN c.price_cents ELSE 0 END);
 FOR a IN SELECT value FROM jsonb_array_elements(cart) LOOP INSERT INTO order_items(order_id,item_type,addon_key,description,quantity,unit_cents) VALUES(oid,'addon',a->>'id',a->>'name',(a->>'quantity')::int,(a->>'unit_cents')::int); END LOOP;
 RETURN jsonb_build_object('id',oid,'status','pending','total',total);
END $$;
REVOKE ALL ON FUNCTION public.create_challenge_order(uuid,uuid,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_challenge_order(uuid,uuid,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.reconcile_challenge_order(_order uuid,_session text,_intent text,_amount integer,_currency text,_environment text,_state text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o orders; c challenges; extras jsonb; BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_allowed'; END IF;
 SELECT * INTO o FROM orders WHERE id=_order AND offering_type='challenge'; IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
 SELECT * INTO c FROM challenges WHERE id=o.challenge_id FOR UPDATE; SELECT * INTO o FROM orders WHERE id=_order FOR UPDATE;
 IF o.stripe_checkout_session_id IS DISTINCT FROM _session OR o.environment<>_environment OR o.currency<>_currency OR o.gross_cents<>_amount THEN RAISE EXCEPTION 'payment_unverified'; END IF;
 IF _state IN('failed','cancelled') THEN UPDATE orders SET status=_state,updated_at=now() WHERE id=_order AND status='pending'; RETURN; END IF;
 IF _state<>'succeeded' OR _intent NOT LIKE 'pi_%' THEN RAISE EXCEPTION 'payment_unverified'; END IF;
 IF o.status IN('paid','partially_refunded','refunded','disputed') THEN RETURN; END IF;
 IF o.status<>'pending' OR o.reservation_expires_at<=now() OR c.status<>'published' OR EXISTS(SELECT 1 FROM user_suspensions WHERE user_id=o.buyer_user_id) OR NOT EXISTS(SELECT 1 FROM team_members WHERE user_id=o.buyer_user_id AND team_id=c.team_id AND suspended_at IS NULL) OR EXISTS(SELECT 1 FROM team_suspensions WHERE team_id=c.team_id) THEN UPDATE orders SET status='disputed',stripe_payment_intent_id=_intent,updated_at=now() WHERE id=_order; RETURN; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',addon_key,'name',description,'quantity',quantity,'unit_cents',unit_cents)),'[]'::jsonb) INTO extras FROM order_items WHERE order_id=_order AND item_type='addon';
 UPDATE orders SET status='paid',stripe_payment_intent_id=_intent,updated_at=now() WHERE id=_order;
 INSERT INTO challenge_members(challenge_id,user_id,source,access_status,order_id,extras) VALUES(o.challenge_id,o.buyer_user_id,'order','active',o.id,extras) ON CONFLICT(challenge_id,user_id) DO NOTHING;
END $$;
REVOKE ALL ON FUNCTION public.reconcile_challenge_order(uuid,text,text,integer,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reconcile_challenge_order(uuid,text,text,integer,text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.guard_paid_challenge_join() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.source NOT IN('free','payment','order') OR NEW.access_status NOT IN('active','revoked','refunded') THEN RAISE EXCEPTION 'not_allowed'; END IF;
 IF NEW.source='order' AND NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.order_id AND challenge_id=NEW.challenge_id AND buyer_user_id=NEW.user_id AND status IN('paid','partially_refunded') AND stripe_payment_intent_id IS NOT NULL) THEN RAISE EXCEPTION 'payment_required'; END IF;
 IF EXISTS(SELECT 1 FROM challenges WHERE id=NEW.challenge_id AND is_paid) AND NEW.source<>'order' AND (NEW.source<>'payment' OR NOT EXISTS(SELECT 1 FROM payments WHERE id=NEW.payment_id AND challenge_id=NEW.challenge_id AND status='paid' AND stripe_payment_intent IS NOT NULL AND buyer_key=NEW.user_id::text)) THEN RAISE EXCEPTION 'payment_required'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.challenge_member_active(_c uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM challenge_members m JOIN challenges c ON c.id=m.challenge_id WHERE c.id=_c AND m.user_id=_user AND m.access_status='active' AND c.status='published' AND EXISTS(SELECT 1 FROM team_members WHERE team_id=c.team_id AND user_id=_user AND suspended_at IS NULL) AND NOT EXISTS(SELECT 1 FROM team_suspensions WHERE team_id=c.team_id) AND NOT EXISTS(SELECT 1 FROM user_suspensions WHERE user_id=_user) AND (NOT c.is_paid OR (m.source='order' AND EXISTS(SELECT 1 FROM orders WHERE id=m.order_id AND challenge_id=c.id AND buyer_user_id=_user AND status IN('paid','partially_refunded') AND stripe_payment_intent_id IS NOT NULL)) OR (m.source='payment' AND EXISTS(SELECT 1 FROM payments WHERE id=m.payment_id AND challenge_id=c.id AND status='paid' AND stripe_payment_intent IS NOT NULL AND buyer_key=_user::text)))); $$;
CREATE OR REPLACE FUNCTION public.challenge_order_receipts(_c uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'status',o.status,'currency',o.currency,'total',o.gross_cents,'created_at',o.created_at,'lines',(SELECT jsonb_agg(jsonb_build_object('id',i.id,'kind',i.item_type,'name',i.description,'quantity',i.quantity,'unit_cents',i.unit_cents,'refunded_cents',i.refunded_cents) ORDER BY i.created_at,i.id) FROM order_items i WHERE i.order_id=o.id)) ORDER BY o.created_at DESC),'[]'::jsonb) FROM orders o WHERE o.challenge_id=_c AND auth.uid() IS NOT NULL AND (o.buyer_user_id=auth.uid() OR can_manage_challenge(_c)); $$;
REVOKE ALL ON FUNCTION public.challenge_order_receipts(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.challenge_order_receipts(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.reconcile_challenge_refund(_order uuid,_provider_refund text,_status text,_amount integer,_lines jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o orders; r refunds; x jsonb; i order_items; total int; base_refunded boolean; BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR _status NOT IN('pending','failed','succeeded') OR _amount<=0 OR jsonb_typeof(_lines) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'not_allowed'; END IF;
 SELECT * INTO o FROM orders WHERE id=_order AND offering_type='challenge' FOR UPDATE; IF NOT FOUND OR o.stripe_payment_intent_id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
 SELECT * INTO r FROM refunds WHERE stripe_refund_id=_provider_refund FOR UPDATE; IF FOUND AND r.status='succeeded' THEN RETURN; END IF;
 SELECT coalesce(sum((value->>'amount')::int),0) INTO total FROM jsonb_array_elements(_lines); IF total<>_amount OR _amount>o.gross_cents OR (SELECT count(*) FROM jsonb_array_elements(_lines))<>(SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(_lines)) THEN RAISE EXCEPTION 'invalid_refund'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(_lines) LOOP SELECT * INTO i FROM order_items WHERE id=(x->>'id')::uuid AND order_id=_order FOR UPDATE; IF NOT FOUND OR (x->>'amount')::int<=0 OR i.refunded_cents+(x->>'amount')::int>i.quantity*i.unit_cents THEN RAISE EXCEPTION 'invalid_refund'; END IF; END LOOP;
 INSERT INTO refunds(order_id,idempotency_key,reason,amount_cents,status,stripe_refund_id) VALUES(_order,'challenge-refund:'||_provider_refund,'other',_amount,_status,_provider_refund) ON CONFLICT(stripe_refund_id) DO UPDATE SET status=EXCLUDED.status;
 IF _status<>'succeeded' THEN RETURN; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(_lines) LOOP UPDATE order_items SET refunded_cents=refunded_cents+(x->>'amount')::int WHERE id=(x->>'id')::uuid AND order_id=_order; END LOOP;
 SELECT sum(refunded_cents) INTO total FROM order_items WHERE order_id=_order;
 SELECT EXISTS(SELECT 1 FROM order_items WHERE order_id=_order AND item_type='challenge' AND unit_cents>0 AND refunded_cents>=unit_cents*quantity) INTO base_refunded;
 IF base_refunded THEN UPDATE challenge_members SET access_status='refunded' WHERE order_id=_order; END IF;
 UPDATE orders SET status=CASE WHEN total>=gross_cents THEN 'refunded' ELSE 'partially_refunded' END,updated_at=now() WHERE id=_order;
END $$;
REVOKE ALL ON FUNCTION public.reconcile_challenge_refund(uuid,text,text,integer,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reconcile_challenge_refund(uuid,text,text,integer,jsonb) TO service_role;